mapper.select:
SELECT vc.id, vc.video_id AS videoId, v.title AS videoTitle, vc.user_id AS userId, u.username, u.nickname, vc.parent_id AS parentId, vc.content, vc.status, vc.created_at AS createdAt, vc.deleted_at AS deletedAt FROM video_comment vc INNER JOIN sys_user u ON u.id = vc.user_id INNER JOIN video v ON v.id = vc.video_id WHERE 1 = 1 AND vc.status = #{status} AND vc.video_id = #{videoId}
AND (vc.content LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR v.title LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY vc.created_at DESC, vc.id DESC
